import { prependHexPrefix, reverseHexByteOrder, trimHexPrefix, } from "./encoder.js";
export const isSameScriptTemplate = (lock1, lock2) => {
    return lock1.codeHash === lock2.codeHash && lock1.hashType === lock2.hashType;
};
export const isUsingOneOfScripts = (script, scripts) => {
    return (scripts.length > 0 && scripts.some((s) => isSameScriptTemplate(s, script)));
};
export const updateScriptArgsWithTxId = (args, txId) => {
    const argsLength = trimHexPrefix(args).length;
    if (argsLength < (32 + 2) * 2) {
        throw new Error("Lock args length is invalid");
    }
    return prependHexPrefix(`${trimHexPrefix(args).substring(0, argsLength - 32 * 2)}${trimHexPrefix(reverseHexByteOrder(prependHexPrefix(txId)))}`);
};
export function getTxIdFromScriptArgs(args) {
    if (args.length < 32 * 2) {
        throw new Error("Lock args length is invalid");
    }
    return trimHexPrefix(reverseHexByteOrder(args.substring(args.length - 32 * 2)));
}
export function getTxIndexFromScriptArgs(args) {
    if (args.length < 32 * 2) {
        throw new Error("Lock args length is invalid");
    }
    return parseInt(reverseHexByteOrder(trimHexPrefix(args.substring(0, 8))), 16);
}
export function parseUtxoSealFromScriptArgs(args) {
    return {
        txId: getTxIdFromScriptArgs(args),
        index: getTxIndexFromScriptArgs(args),
    };
}
